import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, vec3 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  const root = new THREE.Group();

  const visual = config.intent?.visualSpec ?? {};
  const colors = visual.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const atlas = { x: 0, y: 0, w: 512, h: 320 };
  const aspect = atlas.w / atlas.h;
  const height = 2.0;
  const width = height * aspect;

  const geometry = new THREE.PlaneGeometry(width, height);
  const material = new THREE.MeshBasicNodeMaterial({
    transparent: true,
    side: THREE.DoubleSide,
    depthWrite: false,
  });

  const surfaceColor = new THREE.Color(colors.surface);
  material.color = surfaceColor;
  material.colorNode = vec3(surfaceColor);

  let loadedTex = null;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTex = tex;
      tex.colorSpace = THREE.SRGBColorSpace;

      const imgW = tex.image?.width || atlas.w;
      const imgH = tex.image?.height || atlas.h;
      tex.repeat.set(atlas.w / imgW, atlas.h / imgH);
      tex.offset.set(atlas.x / imgW, atlas.y / imgH);

      const texNode = texture(tex);
      material.colorNode = texNode.rgb;
      material.opacityNode = texNode.a;
      material.needsUpdate = true;
    });
  }

  const mesh = new THREE.Mesh(geometry, material);
  root.add(mesh);

  root.userData.handlers = {
    update: (_time, camera) => {
      root.lookAt(camera.position);
    },
  };

  root.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (loadedTex) loadedTex.dispose();
  };

  return root;
}
